import{_ as a,c as o,o as r,ag as i}from"./chunks/framework.ARG558ZT.js";const h=JSON.parse('{"title":"I see from your self presentation you are working with AWS. Could you please provide some examples of Pros & Cons?","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/Other/I_see_from_your_self_presentation_you_are_working_with_AWS._Could_you_please_provide_some_examples_of_Pros_&_Cons.md","filePath":"senior_growth/Other/I_see_from_your_self_presentation_you_are_working_with_AWS._Could_you_please_provide_some_examples_of_Pros_&_Cons.md"}'),t={name:"senior_growth/Other/I_see_from_your_self_presentation_you_are_working_with_AWS._Could_you_please_provide_some_examples_of_Pros_&_Cons.md"};function s(l,e,n,c,d,u){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="i-see-from-your-self-presentation-you-are-working-with-aws-could-you-please-provide-some-examples-of-pros-cons" tabindex="-1">I see from your self presentation you are working with AWS. Could you please provide some examples of Pros &amp; Cons? <a class="header-anchor" href="#i-see-from-your-self-presentation-you-are-working-with-aws-could-you-please-provide-some-examples-of-pros-cons" aria-label="Permalink to “I see from your self presentation you are working with AWS. Could you please provide some examples of Pros &amp; Cons?”">​</a></h1><h2 id="🔹-aws-pros-cons" tabindex="-1">🔹 AWS: Pros &amp; Cons <a class="header-anchor" href="#🔹-aws-pros-cons" aria-label="Permalink to “🔹 AWS: Pros &amp; Cons”">​</a></h2><p>This is study material, not a claim of personal/employer AWS deployment experience. Use the <a href="./../../node-js/aws-service-slice.html">concrete service-slice lesson</a> for a locally linted topology/IAM/IaC and workload-cost example; cloud execution remains learner practice.</p><p><strong>Amazon Web Services (AWS)</strong> is a leading <strong>cloud computing platform</strong> providing a wide range of services including <strong>compute, storage, databases, networking, machine learning, and more</strong>. While it’s extremely popular, there are trade-offs to consider.</p><hr><h2 id="_1️⃣-pros-of-aws" tabindex="-1">1️⃣ Pros of AWS <a class="header-anchor" href="#_1️⃣-pros-of-aws" aria-label="Permalink to “1️⃣ Pros of AWS”">​</a></h2><h3 id="_1-1-scalability-flexibility" tabindex="-1">1.1 Scalability &amp; Flexibility <a class="header-anchor" href="#_1-1-scalability-flexibility" aria-label="Permalink to “1.1 Scalability &amp; Flexibility”">​</a></h3><ul><li>Scale capacity subject to startup time, configured policies, quotas and available resources; response is not instantaneous.</li><li>Supports <strong>auto-scaling</strong> for applications.</li><li>Variety of compute options: <strong>EC2, Lambda (serverless), ECS, EKS</strong>.</li></ul><h3 id="_1-2-global-infrastructure" tabindex="-1">1.2 Global Infrastructure <a class="header-anchor" href="#_1-2-global-infrastructure" aria-label="Permalink to “1.2 Global Infrastructure”">​</a></h3><ul><li>Data centers in <strong>multiple regions and availability zones (AZs)</strong>.</li><li>Reduces latency by <strong>serving users from nearby regions</strong>.</li><li>Availability/fault tolerance depend on the selected service, explicit multi-AZ design and tested recovery.</li></ul><h3 id="_1-3-broad-service-offering" tabindex="-1">1.3 Broad Service Offering <a class="header-anchor" href="#_1-3-broad-service-offering" aria-label="Permalink to “1.3 Broad Service Offering”">​</a></h3><ul><li>Compute: EC2, Lambda, Fargate</li><li>Storage: S3, EBS, Glacier</li><li>Databases: RDS, DynamoDB, Redshift</li><li>Networking: VPC, CloudFront, API Gateway</li><li>Security: IAM, KMS, WAF, Shield</li><li>DevOps: CodePipeline, CodeBuild, CloudWatch</li></ul><h3 id="_1-4-pay-as-you-go" tabindex="-1">1.4 Pay-as-You-Go <a class="header-anchor" href="#_1-4-pay-as-you-go" aria-label="Permalink to “1.4 Pay-as-You-Go”">​</a></h3><ul><li>Only pay for the <strong>resources you use</strong>.</li><li>Supports <strong>reserved instances</strong> for predictable workloads to save costs.</li><li>Reduces <strong>upfront infrastructure investment</strong>.</li></ul><h3 id="_1-5-security-compliance" tabindex="-1">1.5 Security &amp; Compliance <a class="header-anchor" href="#_1-5-security-compliance" aria-label="Permalink to “1.5 Security &amp; Compliance”">​</a></h3><ul><li>Provides <strong>strong security controls</strong>: IAM, encryption at rest/in-transit, audit logging.</li><li>Provides compliance attestations/programs for defined service scopes; customer application/configuration/data obligations remain under the shared-responsibility model.</li></ul><h3 id="_1-6-high-reliability" tabindex="-1">1.6 High Reliability <a class="header-anchor" href="#_1-6-high-reliability" aria-label="Permalink to “1.6 High Reliability”">​</a></h3><ul><li>Some services provide multi-AZ behavior; other workloads require explicit multi-AZ provisioning.</li><li>Storage durability targets vary by service/class and differ from availability or protection from bad writes/deletion.</li></ul><hr><h2 id="_2️⃣-cons-of-aws" tabindex="-1">2️⃣ Cons of AWS <a class="header-anchor" href="#_2️⃣-cons-of-aws" aria-label="Permalink to “2️⃣ Cons of AWS”">​</a></h2><h3 id="_2-1-cost-complexity" tabindex="-1">2.1 Cost Complexity <a class="header-anchor" href="#_2-1-cost-complexity" aria-label="Permalink to “2.1 Cost Complexity”">​</a></h3><ul><li>Pay-as-you-go can be <strong>hard to estimate</strong>.</li><li>Overprovisioning or leaving resources running can lead to <strong>unexpected high bills</strong>.</li><li>Requires <strong>cost monitoring and optimization</strong>.</li></ul><h3 id="_2-2-learning-curve" tabindex="-1">2.2 Learning Curve <a class="header-anchor" href="#_2-2-learning-curve" aria-label="Permalink to “2.2 Learning Curve”">​</a></h3><ul><li>AWS has a broad and changing service catalog; focus on the workload&#39;s compute/storage/network/IAM needs rather than memorize a count.</li><li>Requires understanding <strong>IAM, networking, storage types, service limits</strong>.</li><li>Configuration mistakes can lead to <strong>security or availability issues</strong>.</li></ul><h3 id="_2-3-vendor-lock-in" tabindex="-1">2.3 Vendor Lock-in <a class="header-anchor" href="#_2-3-vendor-lock-in" aria-label="Permalink to “2.3 Vendor Lock-in”">​</a></h3><ul><li>AWS-specific services and APIs may make it <strong>hard to migrate</strong> to another cloud provider.</li><li>Using managed services like DynamoDB or Lambda can tie you heavily to AWS.</li></ul><h3 id="_2-4-complexity-for-small-projects" tabindex="-1">2.4 Complexity for Small Projects <a class="header-anchor" href="#_2-4-complexity-for-small-projects" aria-label="Permalink to “2.4 Complexity for Small Projects”">​</a></h3><ul><li>For small apps or startups, AWS can be <strong>overkill</strong>.</li><li>Requires <strong>architecture planning</strong> even for simple deployments.</li></ul><h3 id="_2-5-service-limits-quotas" tabindex="-1">2.5 Service Limits &amp; Quotas <a class="header-anchor" href="#_2-5-service-limits-quotas" aria-label="Permalink to “2.5 Service Limits &amp; Quotas”">​</a></h3><ul><li>Some services have <strong>soft limits</strong> (API calls, EC2 instances).</li><li>You may need to <strong>request quota increases</strong> for scaling.</li></ul><hr><h2 id="_3️⃣-example-use-cases" tabindex="-1">3️⃣ Example Use Cases <a class="header-anchor" href="#_3️⃣-example-use-cases" aria-label="Permalink to “3️⃣ Example Use Cases”">​</a></h2><table tabindex="0"><thead><tr><th>Use Case</th><th>AWS Service</th><th>Reason for Choosing</th></tr></thead><tbody><tr><td>Web Application Hosting</td><td>EC2 + RDS + S3</td><td>Scalable, durable storage, managed DB</td></tr><tr><td>Static Website</td><td>S3 + CloudFront</td><td>Cheap, fast, global distribution</td></tr><tr><td>Serverless API</td><td>Lambda + API Gateway</td><td>No server management, auto-scaling</td></tr><tr><td>Data Analytics</td><td>Redshift + Athena + S3</td><td>Scalable queries on big datasets</td></tr><tr><td>Machine Learning</td><td>SageMaker</td><td>Managed ML workflows</td></tr></tbody></table><hr><h3 id="✅-summary" tabindex="-1">✅ Summary <a class="header-anchor" href="#✅-summary" aria-label="Permalink to “✅ Summary”">​</a></h3><p><strong>Pros:</strong></p><ul><li>Scalable, reliable, globally available</li><li>Broad range of services</li><li>Pay-as-you-go, strong security &amp; compliance</li></ul><p><strong>Cons:</strong></p><ul><li>Cost can grow unexpectedly</li><li>Steep learning curve</li><li>Vendor lock-in, service limits</li></ul><blockquote><p>💡 Senior Tip:<br> Always <strong>monitor costs</strong> and use <strong>Infrastructure as Code (IaC)</strong> like <strong>Terraform</strong> or <strong>CloudFormation</strong> to manage AWS resources safely and reproducibly.</p></blockquote><h2 id="concrete-learning-checkpoint" tabindex="-1">Concrete learning checkpoint <a class="header-anchor" href="#concrete-learning-checkpoint" aria-label="Permalink to “Concrete learning checkpoint”">​</a></h2><p>The <a href="./../../node-js/aws-service-slice.html">AWS service slice</a> selects private Fargate→PostgreSQL with distinct deployment/execution/application identities, one tenant S3 read prefix, digest-pinned images and explicitly owned network/secret prerequisites. Its CloudFormation schema/negative checks and hypothetical cost arithmetic have run locally. Effective account IAM, real deployment, region-specific quote, alerts and teardown have not. Complete the linked acceptance exercise and retain actual outcomes before describing personal implementation experience. CloudFormation is the chosen IaC example; Kubernetes administration is optional beyond awareness at this target depth.</p>',42)])])}const m=a(t,[["render",s]]);export{h as __pageData,m as default};
